function fresh(){const u=S.meta?.updatedAt;if(!u)return"";const d=ymd(new Date(u));return d===today()?"Agenda mis à jour ce matin.":"Agenda mis à jour le "+dshort(d)+".";}

/* ---------- marée : carte compacte avec courbe ---------- */
function dayCurve(s){const m=Date.parse(s+"T12:00:00Z"),pts=[];
  for(let t=m-15*36e5;t<=m+15*36e5;t+=15*6e4){const d=new Date(t);if(ymd(d)!==s)continue;const[H,M]=hm(d).split("h").map(Number);pts.push([H*60+M,hAt(t)]);}
  return pts.map((p,i)=>(i?"L":"M")+p[0]+" "+(96-p[1]/7*90).toFixed(1)).join(" ");}
function tideCard(s,o={}){const t=today(),now=Date.now();
  if(!o.big&&s===t&&!tidesOfDay(t).some(e=>e.ms>now)){s=addDays(t,1);o={...o,label:"Demain "+F(noon(s),{weekday:"long"})};}
  const ts=tidesOfDay(s),c=maxCoef(s),lows=dayLows(s);
  const coefs=ts.filter(e=>e.coef).map(e=>e.coef),cTxt=coefs.length>1&&coefs[0]!==coefs[coefs.length-1]?`Coef. ${coefs[0]} → ${coefs[coefs.length-1]}`:c?`Coef. ${c}`:"";
  let head;if(s===t){const nx=ts.find(e=>e.ms>now),tm=tidesOfDay(addDays(t,1))[0];head=nx?`${nx.k==="BM"?"Basse mer":"Pleine mer"} à ${hm(new Date(nx.ms))}`:tm?`${tm.k==="BM"?"Basse mer":"Pleine mer"} demain à ${hm(new Date(tm.ms))}`:"Prochaine marée demain";}
  else{const b=lows[0]||ts.find(e=>e.k==="BM");head=b?`Basse mer à ${hm(new Date(b.ms))}`:"Marée";}
  let hint="";
  const lw=s===t?lows.filter(l=>l.ms+75*6e4>now):lows;
  if(c>=70&&lw.length){const L=lw[0].ms;hint=`${c>=90?"Grande marée":"Bon coefficient"} : pêche à pied de ${hm(new Date(L-75*6e4))} à ${hm(new Date(L+75*6e4))}.`;}
  else if(c&&c<55)hint=`Mortes-eaux : petite marée, pas de pêche à pied.`;
  else{const p=ts.filter(e=>e.k==="PM"&&(s!==t||e.ms>now));hint=p.length?`Pleine mer à ${p.map(e=>hm(new Date(e.ms))).join(" et ")}.`:"";}
  const dotH=s===t?(()=>{const[H,M]=hm(new Date()).split("h").map(Number);return `<span class="tide-dot" style="left:${((H*60+M)/14.4).toFixed(2)}%;top:${(96-hAt(now)/7*90).toFixed(1)}%"></span>`;})():"";
  const path=dayCurve(s);
  return `<div class="tide ${o.big?"tide-big":""}">
   <div class="tide-top"><span class="tide-label">${o.label||(s===t?"Marée à Préfailles":"Marée "+F(noon(s),{weekday:"long"}))}</span><span class="tide-coef">${cTxt}</span></div>
   <p class="tide-next">${head}</p>${hint?`<p class="tide-hint">${hint}</p>`:""}
   <div class="tide-plot"><svg class="tide-curve" viewBox="0 0 1440 100" preserveAspectRatio="none" aria-hidden="true"><path class="area" d="${path} L1440 100 L0 100Z"/><path class="wave" d="${path}"/></svg>${dotH}</div>
   <div class="tide-times" style="grid-template-columns:repeat(${Math.max(ts.length,3)},1fr)">${ts.map(e=>`<div class="${s===t&&e.ms<now?"is-past":""}"><span>${e.k==="PM"?"Haute":"Basse"}</span><b>${hm(new Date(e.ms))}</b>${o.big?`<span class="tide-h">${e.h.toFixed(1).replace(".",",")} m${e.coef?" · "+e.coef:""}</span>`:""}</div>`).join("")}</div>
   ${o.link===false?"":`<a class="tide-link" href="#mer">${o.linkText||"La mer : vent, houle, eau et spots"}${ic("chev","i-s")}</a>`}</div>`;}

